  /* "셋업제외불펜" 은 글자만 보면 마무리까지 걸리지만, 마무리는 (셋업/마무리) 변형이
     따로 담당한다. 둘 다 풀에 넣으면 한 선수가 두 변형을 갖는 셈이라 중계로만 본다. */
  if (q.indexOf("셋업제외") >= 0) { delete r["마무리"]; r["중계"] = 1; }
